{
  "characters": [
    {
      "id": "yoriko",
      "want": "支所の職を失わずに定年まで勤め上げること",
      "need": "自分の手で書いた下書きの数字を、誰かが後から辿れる形で残すこと",
      "fear": "自分が零と書いたことで、最初から誰もいなかったことになること",
      "wound": "閉山前の陳情書を規定どおり処理して握り潰した記憶",
      "secret": "火鉢で焼くはずだった下書きの頁を裏表紙の袋に挟んだこと",
      "principle": "命令された清書は一字も違えずに行い、命令されていない余白だけを自分のものにする",
      "self_view": "規則に従うだけの地味な事務員",
      "others_view": [
        "支所長から見れば口数の少ない従順な記録係"
      ],
      "predictions": [
        {
          "situation": "上役から死者欄を零で清書し直すよう命じられたとき",
          "choice": "抗議せずに新しい紙を出して零と書く"
        },
        {
          "situation": "書き損じの下書きを火鉢で焼くよう言われたとき",
          "choice": "白紙の端だけを燃やして煙を立て、本紙は定規で切り取って残す"
        },
        {
          "situation": "後任に帳面を引き継ぐとき",
          "choice": "言葉では何も説明せず、閲覧簿の裏表紙の袋ごと棚の奥へ置く"
        }
      ],
      "speech": {
        "sample": "「清書は終わりました。検印はこちらの欄にお願いいたします。書き損じの紙は、宿直の火鉢で始末しておきます」",
        "vocab": [
          "清書",
          "検印",
          "綴じ込み"
        ],
        "avoid": [
          "真実",
          "告発"
        ]
      },
      "arc": {
        "endpoint": "命じられた零の本欄と、切り取った控えの両方を同じ一冊の帳面に収めて棚へ戻す",
        "changed": [
          "書き損じを規定どおり焼却せず、裏表紙の袋へ隠して残す"
        ],
        "unchanged": [
          "上役の前では一言も反論せず、本欄の清書は命じられた通りに仕上げる"
        ]
      },
      "bans": [
        "上役を怒鳴りつける",
        "帳面の本欄を勝手に書き換える"
      ]
    },
    {
      "id": "kuroda",
      "want": "閉山手続きを波風なく終えて本庁へ戻ること",
      "need": "支所の帳面が後年まで残る重さを認めること",
      "fear": "閉山時の事故の扱いで本庁から責任を問われること",
      "wound": "かつての炭鉱閉山で記録の食い違いから左遷されたこと",
      "secret": "入坑記録の控えを見ないまま零での確定を急いだこと",
      "principle": "紙に書かれなかったことは行政上は起きなかったことと同じだと考える",
      "self_view": "町と支所を守る実務家",
      "others_view": [
        "頼子から見れば、自分の検印が持つ重さから目を逸らしている上役"
      ],
      "predictions": [
        {
          "situation": "下書きの死者欄に名前があるのを見たとき",
          "choice": "入坑記録の不備を理由に零での清書を命じる"
        },
        {
          "situation": "清書された帳面を受け取ったとき",
          "choice": "中身を読み返さずに検印だけを押して帰る"
        },
        {
          "situation": "火鉢の灰を見たとき",
          "choice": "下書きが焼かれたものと思い込んで確かめない"
        }
      ],
      "speech": {
        "sample": "「入坑の記録が揃っておらん以上、事故死者の欄は零で確定する。今夜のうちに清書し直して、古い紙は火鉢で焼いておけ」",
        "vocab": [
          "確定",
          "本庁",
          "始末"
        ],
        "avoid": [
          "謝罪",
          "記憶"
        ]
      },
      "arc": {
        "endpoint": "検印を押して支所を出ていき、裏表紙の袋に控えが残ったことに気づかない",
        "changed": [
          "なし（一夜の場面のため変化しない）"
        ],
        "unchanged": [
          "手続きの完了だけを見て、紙の行方を確かめない"
        ]
      },
      "bans": [
        "自分で下書きを焼く",
        "坑夫の家族に会いに行く"
      ]
    }
  ]
}
